import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { ApplicationConfig } from 'espd-common/config';
import { Observable, of, Subject } from 'rxjs';
import { filter, map, share, take, tap } from 'rxjs/operators';
import { MessageConfig } from './message-config.class';

@Injectable()
export class MessageService {

	private messages: Record<string, string> = {};
	private loadedModules: string[] = [];

	private dataUpdateSubject = new Subject<string>();

	public readonly onDataUpdate: Observable<string> = this.dataUpdateSubject.asObservable();

	private http = inject(HttpClient);
	private config = inject(ApplicationConfig);

	public init(module: string): Observable<object> {
		const obs = this.http.get(`${this.config.messagePath}?module=${module}`)
			.pipe(
				tap(data => Object.assign(this.messages, data)),
				share()
			);
		obs.subscribe(() => {
			this.loadedModules.push(module);
			this.dataUpdateSubject.next(module);
		});
		return obs;
	}

	public waitFor(...modules: string[]): Observable<void> {
		if (this.loadedModules.some(item => modules.includes(item))) {
			return of(void 0);
		} else {
			return this.onDataUpdate.pipe(filter(m => modules.includes(m)), take(1), map(_m => void 0));
		}
	}

	public get(key: string, ...args: unknown[]): string {
		let value: string = this.messages[key];

		if (!value) {
			console.debug('Message not found:', key);
			value = '';
		}

		for (let i = 0; i < args.length; i++) {
			value = value.replace(new RegExp(`\\{${i}\\}`, 'g'), args[i]?.toString() ?? '');
		}

		return value;
	}

	public evaluate(config: MessageConfig | string): string {
		if (config) {
			if (typeof config === 'string') {
				return config;
			} else {
				if (config.text) {
					return config.text;
				} else if (config.key) {
					return this.get(config.key, ...(config.args ?? []));
				}
			}
		}
		return '';
	}
}