import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { SettingService } from 'espd-common/setting';
import { MessageConfig } from './message-config.class';
import { MessageService } from './message.service';

@Component({
	selector: 'espd-message',
	template: '@if (setting()) {<span [innerHTML]="settingValue()"></span>} @else {{{message()}}}',
	changeDetection: ChangeDetectionStrategy.OnPush
})
export class MessageComponent {
	public key = input<string>();
	public args = input<unknown[]>();
	public setting = input<string>();
	public config = input<MessageConfig | string>();
	public settingValue = computed(() => this.computeSetting());
	public message = computed(() => this.computeMessage());
	private messageService = inject(MessageService);
	private settingService = inject(SettingService);
	private messageUpdateSignal = toSignal(this.messageService.onDataUpdate);
	private settingUpdateSignal = toSignal(this.settingService.onDataUpdate);

	private computeMessage(): string {
		this.messageUpdateSignal(); // required for being responsive to the async calls
		if (this.config()) {
			return this.messageService.evaluate(this.config()!);
		} else if (this.key()) {
			return this.messageService.get(this.key()!, ...(this.args() ?? []));
		} else {
			return '';
		}
	}

	private computeSetting(): string | undefined {
		this.settingUpdateSignal(); // required for being responsive to the async calls
		return (this.settingService.get(this.setting()!) ?? '') as string;
	}
}